import java.util.*;

class Solution {
    public List<String> maxNumOfSubstrings(String s) {
            int n = s.length();
                    int[] first = new int[26];
                            int[] last = new int[26];
                                    Arrays.fill(first, n);
                                            Arrays.fill(last, -1);

                                                    for (int i = 0; i < n; i++) {
                                                                int idx = s.charAt(i) - 'a';
                                                                            first[idx] = Math.min(first[idx], i);
                                                                                        last[idx] = Math.max(last[idx], i);
                                                                                                }

                                                                                                        List<String> ans = new ArrayList<>();
                                                                                                                int lastEnd = -1;

                                                                                                                        for (int i = 0; i < n; i++) {
                                                                                                                                    if (i == first[s.charAt(i) - 'a']) {
                                                                                                                                                    int right = getValidRight(s, i, first, last);
                                                                                                                                                                    if (right != -1) {
                                                                                                                                                                                        if (i <= lastEnd) {
                                                                                                                                                                                                                ans.set(ans.size() - 1, s.substring(i, right + 1));
                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                            ans.add(s.substring(i, right + 1));
                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                    lastEnd = right;
                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                return ans;
                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                        private int getValidRight(String s, int i, int[] first, int[] last) {
                                                                                                                                                                                                                                                                                                                                                                int right = last[s.charAt(i) - 'a'];
                                                                                                                                                                                                                                                                                                                                                                        int j = i;
                                                                                                                                                                                                                                                                                                                                                                                while (j <= right) {
                                                                                                                                                                                                                                                                                                                                                                                            int cIdx = s.charAt(j) - 'a';
                                                                                                                                                                                                                                                                                                                                                                                                        if (first[cIdx] < i) {
                                                                                                                                                                                                                                                                                                                                                                                                                        return -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                right = Math.max(right, last[cIdx]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            j++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return right;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            